package com.citacloud.app.services;
import com.citacloud.app.models.*; import com.citacloud.app.repositories.*; import com.citacloud.app.security.AuthService; import com.citacloud.app.security.TenantUserDetails;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*;
@Service public class InventarioService {
 public record ProductoFila(ProductoInventario producto, BigDecimal stock, String estado){} public record Resumen(long productos,long bajoStock,long agotados,long porVencer){} public record MovimientoSolicitud(UUID productoId,UUID sucursalId,String tipo,String motivo,BigDecimal cantidad,UUID loteId,String numeroLote,LocalDate vencimiento,BigDecimal costo,String referencia,String observacion){}
 private final ProductoInventarioRepository productos; private final CategoriaInventarioRepository categorias; private final UnidadInventarioRepository unidades; private final SucursalRepository sucursales; private final ExistenciaInventarioRepository existencias; private final LoteInventarioRepository lotes; private final MovimientoInventarioRepository movimientos; private final AuditoriaService auditoria;
 public InventarioService(ProductoInventarioRepository p,CategoriaInventarioRepository c,UnidadInventarioRepository u,SucursalRepository s,ExistenciaInventarioRepository e,LoteInventarioRepository l,MovimientoInventarioRepository m,AuditoriaService a){productos=p;categorias=c;unidades=u;sucursales=s;existencias=e;lotes=l;movimientos=m;auditoria=a;}
 @Transactional(readOnly=true) public List<CategoriaInventario> categorias(UUID e){return categorias.findByEmpresaIdAndActivaTrueOrderByNombre(e);} @Transactional(readOnly=true) public List<UnidadInventario> unidades(UUID e){return unidades.findByEmpresaIdAndActivaTrueOrderByNombre(e);} @Transactional(readOnly=true) public List<Sucursal> sucursales(UUID e){return sucursales.findByEmpresaIdAndActivaTrue(e);}
 @Transactional(readOnly=true) public String siguienteCodigo(UUID empresa){return codigoAutomatico(empresa);} @Transactional public CategoriaInventario crearCategoria(UUID empresa,String nombre){if(empresa==null||nombre==null||nombre.isBlank())throw new IllegalArgumentException("El nombre de la categoría es obligatorio.");CategoriaInventario c=new CategoriaInventario();c.setEmpresaId(empresa);c.setNombre(nombre.trim());try{return categorias.save(c);}catch(Exception e){throw new IllegalArgumentException("Ya existe una categoría con ese nombre.");}} @Transactional public UnidadInventario crearUnidad(UUID empresa,String nombre,String abreviatura){if(empresa==null||nombre==null||nombre.isBlank())throw new IllegalArgumentException("El nombre de la unidad es obligatorio.");UnidadInventario u=new UnidadInventario();u.setEmpresaId(empresa);u.setNombre(nombre.trim());u.setAbreviatura(vacio(abreviatura));try{return unidades.save(u);}catch(Exception e){throw new IllegalArgumentException("Ya existe una unidad con ese nombre.");}}
 @Transactional(readOnly=true) public List<ProductoFila> listar(UUID empresa,UUID sucursal){if(empresa==null)return List.of(); return productos.findByEmpresaIdOrderByNombre(empresa).stream().map(p->{BigDecimal stock=stock(empresa,p.getId(),sucursal); return new ProductoFila(p,stock,estado(stock,p.getStockMinimo()));}).toList();}
 @Transactional(readOnly=true) public Resumen resumen(UUID empresa,UUID sucursal){var filas=listar(empresa,sucursal);long porVencer=lotes.findAll().stream().filter(l->l.getEmpresaId().equals(empresa)&&l.getCantidad().signum()>0&&l.getFechaVencimiento()!=null&&!l.getFechaVencimiento().isBefore(LocalDate.now())&&!l.getFechaVencimiento().isAfter(LocalDate.now().plusDays(30))).count();return new Resumen(filas.stream().filter(x->x.producto().isActivo()).count(),filas.stream().filter(x->"BAJO STOCK".equals(x.estado())).count(),filas.stream().filter(x->"AGOTADO".equals(x.estado())).count(),porVencer);}
 @Transactional public ProductoInventario guardar(UUID empresa,UUID id,String nombre,String codigo,String barras,UUID categoria,UUID unidad,String descripcion,BigDecimal minimo,boolean vence,boolean activo){return guardar(empresa,id,nombre,codigo,barras,categoria,unidad,descripcion,minimo,vence,activo,false,null);}
 @Transactional public ProductoInventario guardar(UUID empresa,UUID id,String nombre,String codigo,String barras,UUID categoria,UUID unidad,String descripcion,BigDecimal minimo,boolean vence,boolean activo,boolean esFacturable,BigDecimal precioVenta){if(empresa==null||nombre==null||nombre.isBlank()||minimo==null||minimo.signum()<0)throw new IllegalArgumentException("Nombre y stock mínimo válido son obligatorios.");if(esFacturable&&(precioVenta==null||precioVenta.signum()<=0))throw new IllegalArgumentException("El precio de venta es obligatorio y debe ser mayor que cero para productos facturables.");ProductoInventario p=id==null?new ProductoInventario():productos.findByIdAndEmpresaId(id,empresa).orElseThrow(()->new IllegalArgumentException("Producto no encontrado."));String cod=id==null?(codigo==null||codigo.isBlank()?codigoAutomatico(empresa):codigo.trim().toUpperCase()):(codigo==null||codigo.isBlank()?p.getCodigo():codigo.trim().toUpperCase());if((id==null||!cod.equalsIgnoreCase(p.getCodigo()))&&productos.existsByEmpresaIdAndCodigoIgnoreCase(empresa,cod))throw new IllegalArgumentException("El código ya existe en esta empresa.");p.setEmpresaId(empresa);p.setCodigo(cod);p.setNombre(nombre.trim());p.setCodigoBarras(vacio(barras));p.setCategoria(categorias.findByIdAndEmpresaId(categoria,empresa).orElseThrow(()->new IllegalArgumentException("Categoría inválida.")));p.setUnidad(unidades.findByIdAndEmpresaId(unidad,empresa).orElseThrow(()->new IllegalArgumentException("Unidad inválida.")));p.setDescripcion(vacio(descripcion));p.setStockMinimo(minimo.setScale(2, RoundingMode.HALF_UP));p.setControlaVencimiento(vence);p.setEsFacturable(esFacturable);p.setPrecioVenta(esFacturable?precioVenta.setScale(2,RoundingMode.HALF_UP):null);p.setActivo(activo);TenantUserDetails u=AuthService.getAuthenticatedUser();if(id==null&&u!=null)p.setCreadoPor(u.getUsuarioId());p=productos.save(p);auditoria.registrar(empresa,u==null?null:u.getUsuarioId(),"INVENTARIO",id==null?"CREATE_PRODUCT":"UPDATE_PRODUCT","PRODUCTO_INVENTARIO",p.getId(),p.getCodigo()+" - "+p.getNombre());return p;}
 @Transactional public MovimientoInventario registrarMovimiento(UUID empresa,MovimientoSolicitud r){if(empresa==null||r==null||r.cantidad()==null||r.cantidad().signum()<=0)throw new IllegalArgumentException("La cantidad debe ser mayor que cero."); if(!Set.of("ENTRADA","SALIDA","AJUSTE").contains(r.tipo()))throw new IllegalArgumentException("Tipo de movimiento inválido.");if("AJUSTE".equals(r.tipo())&&(r.motivo()==null||r.motivo().isBlank()))throw new IllegalArgumentException("El motivo es obligatorio para ajustes.");ProductoInventario p=productos.findByIdAndEmpresaId(r.productoId(),empresa).orElseThrow(()->new IllegalArgumentException("Producto no encontrado."));if(!p.isActivo())throw new IllegalArgumentException("No se pueden registrar movimientos para un producto inactivo.");Sucursal s=sucursales.findByIdAndEmpresaId(r.sucursalId(),empresa).orElseThrow(()->new IllegalArgumentException("Sucursal inválida."));ExistenciaInventario ex=existencias.bloquear(empresa,s.getId(),p.getId()).orElseGet(()->{ExistenciaInventario n=new ExistenciaInventario();n.setEmpresaId(empresa);n.setSucursal(s);n.setProducto(p);return n;});BigDecimal anterior=ex.getCantidad(); BigDecimal delta="SALIDA".equals(r.tipo())||("AJUSTE".equals(r.tipo())&&esNegativo(r.motivo()))?r.cantidad().negate():r.cantidad(); BigDecimal posterior=anterior.add(delta);if(posterior.signum()<0)throw new IllegalArgumentException("La cantidad solicitada supera la existencia disponible.");LoteInventario lote=resolverLote(empresa,r,p,s,delta);ex.setCantidad(posterior);existencias.save(ex);MovimientoInventario m=new MovimientoInventario();m.setEmpresaId(empresa);m.setSucursal(s);m.setProducto(p);m.setLote(lote);m.setNumero("MOV-%06d".formatted(movimientos.countByEmpresaId(empresa)+1));m.setTipo(r.tipo());m.setMotivo(r.motivo().trim());m.setCantidad(delta);m.setStockAnterior(anterior);m.setStockPosterior(posterior);m.setCostoUnitario(r.costo());m.setReferencia(vacio(r.referencia()));m.setObservacion(vacio(r.observacion()));TenantUserDetails u=AuthService.getAuthenticatedUser();m.setCreadoPor(u==null?null:u.getUsuarioId());m=movimientos.save(m);auditoria.registrar(empresa,u==null?null:u.getUsuarioId(),"INVENTARIO","CREATE_MOVEMENT","MOVIMIENTO_INVENTARIO",m.getId(),m.getNumero()+" - "+p.getNombre());return m;}
 @Transactional(readOnly=true) public ProductoInventario producto(UUID e,UUID id){return productos.findByIdAndEmpresaId(id,e).orElseThrow(()->new IllegalArgumentException("Producto no encontrado."));} @Transactional(readOnly=true) public List<LoteInventario> lotes(UUID e,UUID producto){return lotes.findByEmpresaIdAndProductoIdOrderByFechaVencimiento(e,producto);} @Transactional(readOnly=true) public List<MovimientoInventario> movimientos(UUID e){return movimientos.findByEmpresaIdOrderByCreadoEnDesc(e);}
 @Transactional(readOnly=true) public List<ExistenciaInventario> existenciasProducto(UUID empresa,UUID producto){producto(empresa,producto);return existencias.findByEmpresaIdAndProductoId(empresa,producto);}
 private LoteInventario resolverLote(UUID empresa,MovimientoSolicitud r,ProductoInventario p,Sucursal s,BigDecimal delta){if(r.loteId()!=null){LoteInventario l=lotes.findByIdAndEmpresaId(r.loteId(),empresa).orElseThrow(()->new IllegalArgumentException("Lote inválido."));if(!l.getProducto().getId().equals(p.getId())||!l.getSucursal().getId().equals(s.getId()))throw new IllegalArgumentException("El lote no corresponde al producto y sucursal.");if(l.getCantidad().add(delta).signum()<0)throw new IllegalArgumentException("La cantidad solicitada supera la existencia disponible del lote.");l.setCantidad(l.getCantidad().add(delta));return lotes.save(l);} if(r.numeroLote()==null||r.numeroLote().isBlank())return null;LoteInventario l=lotes.findByEmpresaIdAndSucursalIdAndProductoIdAndNumeroLote(empresa,s.getId(),p.getId(),r.numeroLote().trim()).orElseGet(()->{LoteInventario n=new LoteInventario();n.setEmpresaId(empresa);n.setSucursal(s);n.setProducto(p);n.setNumeroLote(r.numeroLote().trim());n.setFechaVencimiento(r.vencimiento());return n;});if(l.getCantidad().add(delta).signum()<0)throw new IllegalArgumentException("La cantidad solicitada supera la existencia disponible del lote.");l.setCantidad(l.getCantidad().add(delta));return lotes.save(l);}
 private BigDecimal stock(UUID empresa,UUID producto,UUID sucursal){return existencias.findByEmpresaIdAndProductoId(empresa,producto).stream().filter(x->sucursal==null||x.getSucursal().getId().equals(sucursal)).map(ExistenciaInventario::getCantidad).reduce(BigDecimal.ZERO,BigDecimal::add);} private String estado(BigDecimal s,BigDecimal min){return s.signum()==0?"AGOTADO":s.compareTo(min)<=0?"BAJO STOCK":"DISPONIBLE";} private boolean esNegativo(String motivo){String m=motivo==null?"":motivo.toUpperCase();return m.contains("NEGATIVO")||m.contains("DAÑ")||m.contains("DIFERENCIA");} private String codigoAutomatico(UUID e){int n=productos.findByEmpresaIdOrderByNombre(e).size()+1;String c;do{c="MED-%06d".formatted(n++);}while(productos.existsByEmpresaIdAndCodigoIgnoreCase(e,c));return c;} private String vacio(String s){return s==null||s.isBlank()?null:s.trim();}
}
